begin;
update nexora.modules set description='Construa aplicações PHP conectadas a MySQL, cobrindo requisições, validação, SQL, PDO, CRUD, sessões, segurança e organização em camadas.' where course_id=(select id from nexora.courses where slug='programador-master') and position=5;
update nexora.lessons set objective='Explicar o ciclo requisição-resposta de uma aplicação PHP e diferenciar execução no servidor de código enviado ao navegador.',estimated_minutes=32,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Onde o código PHP é normalmente executado?","options":["No servidor.","No CSS do navegador.","No banco de dados."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O navegador solicita /produtos.php. O usuário nunca recebe o código PHP: recebe apenas a resposta produzida pelo servidor."},{"type":"concept","title":"Como funciona uma aplicação PHP","body":"PHP normalmente executa no servidor a cada requisição. O servidor web recebe a URL, encaminha o arquivo ou rota ao runtime PHP, o código processa entrada, consulta dados quando necessário e gera uma resposta — frequentemente HTML ou JSON. Essa separação é fundamental: segredos e acesso a banco pertencem ao servidor; o navegador recebe somente o resultado autorizado."},{"type":"mechanics","title":"Como aplicar","items":["Diferencie código de servidor do HTML entregue.","Trate cada requisição como entrada potencialmente não confiável.","Mantenha credenciais fora do conteúdo público.","Observe status e resposta gerados pelo servidor."]},{"type":"example","title":"Exemplo","body":"<?php\\n$nome = ''LC'';\\necho ''<h1>Olá, ''.htmlspecialchars($nome).''</h1>'';\\n?>","language":"php"},{"type":"mistake","title":"Erro comum","body":"Colocar senha de banco em JavaScript ou HTML imaginando que ''o PHP vai esconder''. Tudo enviado ao navegador pode ser inspecionado."},{"type":"guided","question":"Onde o código PHP é normalmente executado?","options":["No servidor.","No CSS do navegador.","No banco de dados."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Explicar o ciclo requisição-resposta de uma aplicação PHP e diferenciar execução no servidor de código enviado ao navegador.","Diferencie código de servidor do HTML entregue.","Trate cada requisição como entrada potencialmente não confiável.","Mantenha credenciais fora do conteúdo público."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Como funciona uma aplicação PHP';
update nexora.lessons set objective='Declarar variáveis, manipular strings, números e booleanos e reconhecer conversões necessárias ao receber dados externos.',estimated_minutes=36,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Dados enviados por formulário devem ser tratados inicialmente como:","options":["Entrada não confiável.","Valores garantidos pelo HTML.","Constantes do servidor."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um valor chega por formulário como texto e será usado em cálculo. Antes de confiar nele, o servidor precisa normalizar e validar."},{"type":"concept","title":"Sintaxe, variáveis e tipos em PHP","body":"Variáveis PHP começam com $. A linguagem é dinamicamente tipada, mas isso não elimina a necessidade de entender o tipo do valor em cada etapa. Dados de query string, formulário e headers chegam como entrada externa e frequentemente como texto. Conversões e validações devem ocorrer conscientemente antes de cálculo ou persistência."},{"type":"mechanics","title":"Como aplicar","items":["Nomeie variáveis pelo significado do domínio.","Valide antes de converter ou persistir.","Use concatenação e interpolação com clareza.","Não confie no tipo aparente de entrada HTTP."]},{"type":"example","title":"Exemplo","body":"<?php\\n$preco = 120.50;\\n$quantidade = 2;\\n$total = $preco * $quantidade;\\necho $total;\\n?>","language":"php"},{"type":"mistake","title":"Erro comum","body":"Assumir que $_POST[''idade''] é inteiro porque o campo HTML era type=number. A requisição pode ser construída manualmente."},{"type":"guided","question":"Dados enviados por formulário devem ser tratados inicialmente como:","options":["Entrada não confiável.","Valores garantidos pelo HTML.","Constantes do servidor."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Declarar variáveis, manipular strings, números e booleanos e reconhecer conversões necessárias ao receber dados externos.","Nomeie variáveis pelo significado do domínio.","Valide antes de converter ou persistir.","Use concatenação e interpolação com clareza."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Sintaxe, variáveis e tipos em PHP';
update nexora.lessons set objective='Implementar regras de decisão e repetição em PHP testando condições de fronteira e garantindo término dos laços.',estimated_minutes=40,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual estrutura PHP é direta para percorrer itens de um array?","options":["foreach","switch apenas","include"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O servidor precisa classificar pedidos por valor e gerar uma linha para cada item aprovado."},{"type":"concept","title":"Operadores, condições e laços","body":"Operadores aritméticos, relacionais e lógicos formam regras; if/elseif/else escolhem caminhos; foreach é especialmente útil para coleções; while exige atenção à condição de parada. A regra de negócio deve ser testável independentemente da renderização. Se a condição é complexa, extraia partes para variáveis ou funções nomeadas."},{"type":"mechanics","title":"Como aplicar","items":["Teste valores imediatamente abaixo, no limite e acima.","Use foreach para arrays quando a intenção é percorrer itens.","Evite aninhamento profundo.","Separe cálculo da geração de HTML quando possível."]},{"type":"example","title":"Exemplo","body":"foreach ($pedidos as $pedido) {\\n  if ($pedido[''total''] >= 100) {\\n    $aprovados++;\\n  }\\n}","language":"php"},{"type":"mistake","title":"Erro comum","body":"Misturar echo, consulta SQL e regra de negócio dentro de vários ifs aninhados. O fluxo fica difícil de testar e alterar."},{"type":"guided","question":"Qual estrutura PHP é direta para percorrer itens de um array?","options":["foreach","switch apenas","include"],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Implementar regras de decisão e repetição em PHP testando condições de fronteira e garantindo término dos laços.","Teste valores imediatamente abaixo, no limite e acima.","Use foreach para arrays quando a intenção é percorrer itens.","Evite aninhamento profundo."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Operadores, condições e laços';
update nexora.lessons set objective='Extrair regras em funções com parâmetros, tipos quando úteis e retorno previsível, reduzindo duplicação entre páginas.',estimated_minutes=40,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual função tende a ser mais fácil de testar?","options":["Recebe parâmetros e retorna resultado.","Depende de várias globais.","Sempre escreve diretamente no HTML."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A regra de calcular desconto aparece em cadastro, checkout e relatório. Uma correção precisa ser feita três vezes."},{"type":"concept","title":"Funções e organização de código","body":"Funções permitem nomear comportamento e concentrar uma regra. Parâmetros deixam dependências explícitas; return produz resultado reutilizável. PHP moderno permite type hints e tipos de retorno, úteis para tornar contratos visíveis. Mesmo sem uma arquitetura complexa, separar funções puras de entrada/saída HTTP reduz acoplamento."},{"type":"mechanics","title":"Como aplicar","items":["Extraia regras repetidas.","Passe dependências como parâmetros.","Retorne dados em vez de imprimir dentro da função sem necessidade.","Use nomes que expressem intenção."]},{"type":"example","title":"Exemplo","body":"function calcularDesconto(float $total, float $taxa): float {\\n  return $total * $taxa;\\n}","language":"php"},{"type":"mistake","title":"Erro comum","body":"Criar funções que acessam $_POST, banco e echo ao mesmo tempo. Elas ficam difíceis de reutilizar e testar."},{"type":"guided","question":"Qual função tende a ser mais fácil de testar?","options":["Recebe parâmetros e retorna resultado.","Depende de várias globais.","Sempre escreve diretamente no HTML."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Extrair regras em funções com parâmetros, tipos quando úteis e retorno previsível, reduzindo duplicação entre páginas.","Extraia regras repetidas.","Passe dependências como parâmetros.","Retorne dados em vez de imprimir dentro da função sem necessidade."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Funções e organização de código';
update nexora.lessons set objective='Representar listas e registros em arrays indexados e associativos e transformá-los sem depender de posições mágicas.',estimated_minutes=42,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual estrutura representa melhor um registro de produto em PHP?","options":["Array associativo com chaves nomeadas.","Uma string única.","Um número isolado."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Produtos precisam de nome, preço e estoque. Um array associativo comunica melhor cada campo do que posições 0, 1 e 2."},{"type":"concept","title":"Arrays e manipulação de dados","body":"PHP oferece arrays que podem atuar como listas ou mapas associativos. Arrays indexados funcionam bem para coleções; associativos representam registros com chaves significativas. Funções como array_map, array_filter e array_reduce ajudam a expressar transformações. A estrutura deve ser consistente, especialmente antes de persistir em banco ou converter para JSON."},{"type":"mechanics","title":"Como aplicar","items":["Use chaves significativas para registros.","Mantenha formato consistente entre itens.","Filtre e transforme em etapas legíveis.","Cheque existência de chaves antes de usá-las."]},{"type":"example","title":"Exemplo","body":"$produto = [''nome''=>''Mouse'',''preco''=>120,''ativo''=>true];\\n$nome = $produto[''nome''];","language":"php"},{"type":"mistake","title":"Erro comum","body":"Acessar chaves opcionais diretamente sem validar existência, gerando warnings e comportamento inesperado."},{"type":"guided","question":"Qual estrutura representa melhor um registro de produto em PHP?","options":["Array associativo com chaves nomeadas.","Uma string única.","Um número isolado."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Representar listas e registros em arrays indexados e associativos e transformá-los sem depender de posições mágicas.","Use chaves significativas para registros.","Mantenha formato consistente entre itens.","Filtre e transforme em etapas legíveis."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Arrays e manipulação de dados';
update nexora.lessons set objective='Distinguir parâmetros de URL e corpo de formulário e escolher GET ou POST conforme semântica, idempotência e exposição de dados.',estimated_minutes=42,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual método é mais adequado para criar um registro?","options":["POST","GET por padrão","HEAD"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma busca deve ser compartilhável por URL, enquanto um cadastro cria um novo registro e não deve colocar todos os dados na query string."},{"type":"concept","title":"Requisições GET e POST","body":"GET normalmente recupera recursos e seus parâmetros aparecem na URL; POST envia dados no corpo e costuma representar criação ou ação. O método não fornece segurança por si só: HTTPS protege transporte e o servidor ainda precisa validar e autorizar. A escolha deve refletir intenção e comportamento esperado, não apenas ''funcionou''."},{"type":"mechanics","title":"Como aplicar","items":["Use GET para leitura e filtros compartilháveis quando adequado.","Use POST para criação/ação que altera estado.","Valide ambos $_GET e $_POST.","Nunca confie no método como substituto de autorização."]},{"type":"example","title":"Exemplo","body":"$busca = trim($_GET[''q''] ?? '''');\\n$nome = trim($_POST[''nome''] ?? '''');","language":"php"},{"type":"mistake","title":"Erro comum","body":"Usar GET para senha ou dado sensível porque é mais fácil testar. URLs podem aparecer em histórico e logs."},{"type":"guided","question":"Qual método é mais adequado para criar um registro?","options":["POST","GET por padrão","HEAD"],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Distinguir parâmetros de URL e corpo de formulário e escolher GET ou POST conforme semântica, idempotência e exposição de dados.","Use GET para leitura e filtros compartilháveis quando adequado.","Use POST para criação/ação que altera estado.","Valide ambos $_GET e $_POST."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Requisições GET e POST';
update nexora.lessons set objective='Normalizar e validar payloads no servidor e devolver erros úteis sem depender das restrições do formulário HTML.',estimated_minutes=46,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Quem deve repetir validações críticas mesmo que o frontend já valide?","options":["O servidor.","A folha CSS.","O README."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O frontend exige e-mail, mas uma requisição direta envia campo vazio. O servidor precisa rejeitar independentemente da interface."},{"type":"concept","title":"Formulários e validação no servidor","body":"Validação do servidor é a garantia final sobre o dado aceito. Normalize espaços, converta tipos com cuidado, verifique obrigatoriedade, formato e regras de domínio. Erros devem ser específicos o suficiente para correção sem expor detalhes internos. A validação de segurança inclui também limitar tamanho e rejeitar formatos inesperados."},{"type":"mechanics","title":"Como aplicar","items":["Normalize antes de validar.","Use filter_var quando apropriado.","Valide regras de domínio além de formato.","Retorne erros estruturados e não stack traces ao usuário."]},{"type":"example","title":"Exemplo","body":"$email = trim($_POST[''email''] ?? '''');\\nif (!filter_var($email, FILTER_VALIDATE_EMAIL)) {\\n  $erros[''email'']=''E-mail inválido'';\\n}","language":"php"},{"type":"mistake","title":"Erro comum","body":"Confiar em required do HTML. O servidor pode ser chamado sem a página."},{"type":"guided","question":"Quem deve repetir validações críticas mesmo que o frontend já valide?","options":["O servidor.","A folha CSS.","O README."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Normalizar e validar payloads no servidor e devolver erros úteis sem depender das restrições do formulário HTML.","Normalize antes de validar.","Use filter_var quando apropriado.","Valide regras de domínio além de formato."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Formulários e validação no servidor';
update nexora.lessons set objective='Explicar tabela, linha, coluna, chave primária e relacionamento e reconhecer quando um banco relacional é adequado ao domínio.',estimated_minutes=42,lab_type='sql',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Clientes, pedidos e itens estão sendo salvos em arquivos separados. Consultar histórico e garantir vínculos começa a ficar frágil."},{"type":"concept","title":"Introdução a bancos de dados relacionais","body":"Bancos relacionais organizam dados em tabelas com esquema e relações explícitas. Uma chave primária identifica cada linha; chaves estrangeiras conectam entidades. O valor não é apenas armazenar: o banco aplica integridade e permite consultas declarativas. Modelar bem reduz duplicação e inconsistência antes mesmo de escrever SQL."},{"type":"mechanics","title":"Como aplicar","items":["Defina entidades e atributos do domínio.","Escolha uma chave primária estável.","Use relações em vez de repetir dados.","Pense em restrições de integridade."]},{"type":"example","title":"Exemplo","body":"clientes(id, nome, email)\\npedidos(id, cliente_id, total)\\nitens(id, pedido_id, produto, quantidade)","language":"sql"},{"type":"mistake","title":"Erro comum","body":"Criar uma tabela gigante com todas as informações repetidas de cliente em cada pedido."},{"type":"guided","question":"Qual restrição conecta uma linha a outra tabela?","options":["FOREIGN KEY","ORDER BY","LIMIT"],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Explicar tabela, linha, coluna, chave primária e relacionamento e reconhecer quando um banco relacional é adequado ao domínio.","Defina entidades e atributos do domínio.","Escolha uma chave primária estável.","Use relações em vez de repetir dados."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Introdução a bancos de dados relacionais';
update nexora.lessons set objective='Transformar requisitos em tabelas normalizadas com cardinalidades, chaves e restrições que preservem integridade.',estimated_minutes=48,lab_type='data_model',lab_config='{"data_model":{"scenario":"Classifique o papel de cada elemento do modelo de pedidos.","options":["Chave primária","Chave estrangeira","Atributo","Tabela de associação"],"rows":[{"label":"pedidos.id","value":"uuid","answer":0},{"label":"itens.pedido_id","value":"uuid","answer":1},{"label":"produtos.nome","value":"text","answer":2},{"label":"pedido_produtos","value":"tabela","answer":3}],"feedback":"Modelo consistente: identidade, relação, atributo e associação estão separados."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um pedido tem vários itens e cada item pertence a um pedido. Guardar uma lista de itens em uma coluna de texto dificulta consulta e validação."},{"type":"concept","title":"Modelagem de tabelas e relacionamentos","body":"Modelagem relacional separa entidades e relações. Um-para-muitos geralmente usa chave estrangeira no lado ''muitos''. Muitos-para-muitos exige tabela de associação. Tipos e nullability também expressam regras. Normalização não significa fragmentar tudo; significa evitar repetição e dependências inconsistentes."},{"type":"mechanics","title":"Como aplicar","items":["Identifique entidades antes das tabelas.","Defina cardinalidade de cada relação.","Use tabela de associação para muitos-para-muitos.","Expresse obrigatoriedade com NOT NULL quando fizer sentido."]},{"type":"example","title":"Exemplo","body":"pedido_itens(\\n  id PK,\\n  pedido_id FK -> pedidos.id,\\n  produto_id FK -> produtos.id,\\n  quantidade INT NOT NULL\\n)","language":"sql"},{"type":"mistake","title":"Erro comum","body":"Salvar IDs separados por vírgula em uma coluna para representar relacionamento. Isso quebra integridade e consultas."},{"type":"guided","question":"Como modelar muitos produtos em muitos pedidos?","options":["Tabela de associação.","Coluna com CSV de IDs.","Uma tabela por pedido."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Transformar requisitos em tabelas normalizadas com cardinalidades, chaves e restrições que preservem integridade.","Identifique entidades antes das tabelas.","Defina cardinalidade de cada relação.","Use tabela de associação para muitos-para-muitos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Modelagem de tabelas e relacionamentos';
update nexora.lessons set objective='Executar operações CRUD básicas com SQL usando filtros explícitos e compreender o risco de alterações sem WHERE.',estimated_minutes=50,lab_type='sql',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Você precisa consultar produtos caros, inserir um item, corrigir um preço e remover um registro específico."},{"type":"concept","title":"SQL: SELECT, INSERT, UPDATE e DELETE","body":"SELECT lê dados; INSERT cria linhas; UPDATE altera; DELETE remove. WHERE limita o conjunto afetado. Em operações de escrita, a ausência de filtro pode modificar a tabela inteira. Antes de UPDATE/DELETE, é uma boa prática executar um SELECT com o mesmo WHERE para confirmar o alvo."},{"type":"mechanics","title":"Como aplicar","items":["Liste colunas necessárias em consultas reais.","Valide o WHERE com SELECT antes de escrita.","Use parâmetros em código de aplicação.","Evite concatenar entrada de usuário em SQL."]},{"type":"example","title":"Exemplo","body":"SELECT id,nome,preco FROM produtos WHERE preco > 500;\\nUPDATE produtos SET preco=799 WHERE id=42;","language":"sql"},{"type":"mistake","title":"Erro comum","body":"Executar UPDATE produtos SET ativo=false; imaginando que apenas um registro seria alterado."},{"type":"guided","question":"Qual cláusula limita linhas em UPDATE e DELETE?","options":["WHERE","ORDER BY apenas","AS"],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Executar operações CRUD básicas com SQL usando filtros explícitos e compreender o risco de alterações sem WHERE.","Liste colunas necessárias em consultas reais.","Valide o WHERE com SELECT antes de escrita.","Use parâmetros em código de aplicação."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='SQL: SELECT, INSERT, UPDATE e DELETE';
update nexora.lessons set objective='Conectar PHP e MySQL com PDO, executar prepared statements e separar parâmetros de dados da estrutura SQL.',estimated_minutes=52,lab_type='sql',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma busca recebe texto do usuário. Concatenar o valor diretamente na query cria risco de SQL injection."},{"type":"concept","title":"PHP com MySQL usando PDO","body":"PDO oferece uma interface consistente para banco e suporta prepared statements. A instrução SQL define estrutura e placeholders; os valores são enviados separadamente. Isso reduz risco de injeção e evita problemas de escaping manual. A conexão deve usar tratamento de erro adequado e credenciais vindas de configuração segura."},{"type":"mechanics","title":"Como aplicar","items":["Use prepared statements para entrada variável.","Mantenha DSN e credenciais fora do repositório público.","Trate exceções sem exibir segredos.","Retorne dados em formato previsível."]},{"type":"example","title":"Exemplo","body":"$stmt=$pdo->prepare(''SELECT id,nome FROM produtos WHERE nome LIKE :q'');\\n$stmt->execute([''q''=>''%''.$busca.''%'']);\\n$rows=$stmt->fetchAll(PDO::FETCH_ASSOC);","language":"php"},{"type":"mistake","title":"Erro comum","body":"Montar SQL com \"... WHERE nome=''$busca''\". Escaping manual é frágil e mistura dados com código."},{"type":"guided","question":"Qual mecanismo PDO deve ser usado para valores vindos do usuário?","options":["Prepared statements.","Concatenação de strings.","eval."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Conectar PHP e MySQL com PDO, executar prepared statements e separar parâmetros de dados da estrutura SQL.","Use prepared statements para entrada variável.","Mantenha DSN e credenciais fora do repositório público.","Trate exceções sem exibir segredos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='PHP com MySQL usando PDO';
update nexora.lessons set objective='Organizar um fluxo CRUD com validação, persistência e feedback, garantindo que criação, leitura, edição e exclusão tenham regras explícitas.',estimated_minutes=58,lab_type='sql',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma tela de produtos precisa listar, criar, editar e excluir. Cada ação deve validar entrada e tratar falhas do banco."},{"type":"concept","title":"CRUD completo","body":"CRUD é um ciclo, não quatro páginas isoladas. As mesmas regras de domínio devem valer em criação e edição. Exclusão precisa confirmar alvo e restrições. A camada de persistência deve retornar sucesso/erro; a interface transforma isso em feedback. IDs vindos da URL nunca devem ser considerados válidos sem consulta e autorização."},{"type":"mechanics","title":"Como aplicar","items":["Reutilize validações entre create e update.","Valide existência do registro antes de editar/excluir.","Use transações quando várias escritas formam uma única operação.","Diferencie erro de validação, não encontrado e falha interna."]},{"type":"example","title":"Exemplo","body":"Fluxo de update: ler id → carregar registro → validar autorização → normalizar payload → validar → executar UPDATE parametrizado → redirecionar/retornar sucesso."},{"type":"mistake","title":"Erro comum","body":"Executar DELETE diretamente ao receber ?id= sem confirmar registro, permissão ou intenção."},{"type":"guided","question":"Qual regra deve ser compartilhada por criação e edição?","options":["Validação de domínio.","Apenas a cor do botão.","Somente o título da página."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Organizar um fluxo CRUD com validação, persistência e feedback, garantindo que criação, leitura, edição e exclusão tenham regras explícitas.","Reutilize validações entre create e update.","Valide existência do registro antes de editar/excluir.","Use transações quando várias escritas formam uma única operação."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='CRUD completo';
update nexora.lessons set objective='Implementar autenticação baseada em sessão distinguindo identidade, estado autenticado e autorização de acesso.',estimated_minutes=50,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual função PHP é adequada para verificar senha contra hash?","options":["password_verify","md5 simples","base64_decode"],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Após login correto, o servidor precisa lembrar o usuário entre requisições e proteger páginas privadas."},{"type":"concept","title":"Sessões e autenticação","body":"Sessões armazenam estado no servidor associado a um identificador enviado ao cliente por cookie. Após validar credenciais, a aplicação guarda um identificador de usuário na sessão. Em cada rota protegida, verifica identidade e depois autorização. Senhas nunca devem ser armazenadas em texto puro; use password_hash e password_verify."},{"type":"mechanics","title":"Como aplicar","items":["Regere o ID da sessão após login.","Armazene apenas o necessário na sessão.","Use password_hash/password_verify.","Faça logout invalidar o estado de sessão."]},{"type":"example","title":"Exemplo","body":"if (password_verify($senha,$hash)) {\\n  session_regenerate_id(true);\\n  $_SESSION[''user_id'']=$usuario[''id''];\\n}","language":"php"},{"type":"mistake","title":"Erro comum","body":"Guardar senha na sessão ou comparar hashes manualmente. Autenticação precisa usar funções apropriadas de senha."},{"type":"guided","question":"Qual função PHP é adequada para verificar senha contra hash?","options":["password_verify","md5 simples","base64_decode"],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Implementar autenticação baseada em sessão distinguindo identidade, estado autenticado e autorização de acesso.","Regere o ID da sessão após login.","Armazene apenas o necessário na sessão.","Use password_hash/password_verify."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Sessões e autenticação';
update nexora.lessons set objective='Distinguir validação, escaping de saída e parametrização SQL e aplicar cada defesa no ponto correto do fluxo.',estimated_minutes=54,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"O que protege melhor contra SQL injection em valores?","options":["Prepared statements.","htmlspecialchars.","CSS escaping."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um texto salvo no banco contém HTML malicioso; em outra rota, um parâmetro tenta alterar a query SQL. São riscos diferentes e exigem defesas diferentes."},{"type":"concept","title":"Segurança: validação, escaping e SQL injection","body":"Validação decide se um dado é aceitável. Prepared statements impedem que valores virem estrutura SQL. Escaping de saída transforma conteúdo para o contexto em que será exibido, como htmlspecialchars em HTML. Nenhuma dessas técnicas substitui a outra. Segurança também inclui autorização, CSRF conforme o tipo de ação e gestão de segredos."},{"type":"mechanics","title":"Como aplicar","items":["Valide formato e regra de domínio na entrada.","Parametrize SQL.","Escape na saída de acordo com o contexto.","Nunca confie em dado só porque veio do banco."]},{"type":"example","title":"Exemplo","body":"echo htmlspecialchars($comentario, ENT_QUOTES, ''UTF-8'');\\n$stmt=$pdo->prepare(''SELECT * FROM usuarios WHERE email=:email'');","language":"php"},{"type":"mistake","title":"Erro comum","body":"Aplicar addslashes em tudo e considerar o sistema seguro. Contextos diferentes precisam de defesas específicas."},{"type":"guided","question":"O que protege melhor contra SQL injection em valores?","options":["Prepared statements.","htmlspecialchars.","CSS escaping."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Distinguir validação, escaping de saída e parametrização SQL e aplicar cada defesa no ponto correto do fluxo.","Valide formato e regra de domínio na entrada.","Parametrize SQL.","Escape na saída de acordo com o contexto."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Segurança: validação, escaping e SQL injection';
update nexora.lessons set objective='Separar entrada HTTP, regras de negócio, persistência e apresentação em camadas simples que possam evoluir sem duplicação.',estimated_minutes=50,lab_type='checkpoint',lab_config='{"checkpoint":{"question":"Qual separação melhora testabilidade?","options":["Regra de negócio independente de echo e SQL direto.","Tudo no mesmo arquivo.","Views executando DELETE."],"answer":0,"feedback":"Correto."}}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um arquivo PHP de 800 linhas contém HTML, SQL, validação, autenticação e regras de preço. Qualquer alteração arrisca quebrar tudo."},{"type":"concept","title":"Organização em camadas e reutilização","body":"Camadas não exigem framework complexo. Mesmo em PHP puro, é possível separar controller/entrada, serviços ou funções de domínio, repositório/persistência e templates de apresentação. O objetivo é reduzir dependências circulares e permitir testar regras sem precisar montar uma requisição completa ou banco real em cada caso."},{"type":"mechanics","title":"Como aplicar","items":["Separe acesso a banco da renderização.","Concentre regras de domínio em funções/serviços.","Compartilhe validações sem copiar código.","Evite abstração antes de existir repetição real."]},{"type":"example","title":"Exemplo","body":"public/index.php → controller → serviço de produto → repositório PDO → view. Cada parte conhece apenas o necessário."},{"type":"mistake","title":"Erro comum","body":"Criar classes e pastas apenas para parecer arquitetado, sem definir responsabilidades. Camadas úteis reduzem acoplamento observável."},{"type":"guided","question":"Qual separação melhora testabilidade?","options":["Regra de negócio independente de echo e SQL direto.","Tudo no mesmo arquivo.","Views executando DELETE."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Separar entrada HTTP, regras de negócio, persistência e apresentação em camadas simples que possam evoluir sem duplicação.","Separe acesso a banco da renderização.","Concentre regras de domínio em funções/serviços.","Compartilhe validações sem copiar código."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Organização em camadas e reutilização';
update nexora.lessons set objective='Construir um sistema PHP/MySQL com CRUD, autenticação, validação, prepared statements e organização suficiente para publicação e revisão.',estimated_minutes=75,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O projeto final precisa provar que frontend, servidor e banco formam um fluxo coerente e seguro."},{"type":"concept","title":"Projeto: sistema web com banco de dados","body":"Um sistema web de portfólio deve resolver um fluxo real: autenticar, criar e consultar dados, editar com validação e controlar acesso. O banco precisa de modelo coerente; o PHP deve usar prepared statements; a saída deve ser escapada; as responsabilidades não podem ficar todas em um único arquivo. A entrega deve incluir instruções reproduzíveis e dados de demonstração seguros."},{"type":"mechanics","title":"Como aplicar","items":["Defina modelo e fluxo antes de construir telas.","Implemente autenticação e autorização mínimas.","Use validação servidor + prepared statements.","Teste CRUD, erro, acesso indevido e dados inválidos."]},{"type":"example","title":"Exemplo","body":"Escopo sugerido: cadastro/login + painel privado + CRUD de tarefas/clientes/produtos + filtros + sessão + banco relacional + README de instalação."},{"type":"mistake","title":"Erro comum","body":"Publicar com usuário administrador, senha padrão ou arquivo .env dentro do repositório."},{"type":"guided","question":"Qual evidência é indispensável no projeto?","options":["Fluxo CRUD autenticado e testado com dados persistidos.","Somente screenshots.","Muitas bibliotecas."],"answer":0,"hint":"Escolha a alternativa que preserva integridade e segurança.","feedback":"Correto. A decisão está coerente com o fluxo servidor/banco.","feedback_incorrect":"Revise a separação entre entrada, regra, persistência e saída."},{"type":"recap","items":["Construir um sistema PHP/MySQL com CRUD, autenticação, validação, prepared statements e organização suficiente para publicação e revisão.","Defina modelo e fluxo antes de construir telas.","Implemente autenticação e autorização mínimas.","Use validação servidor + prepared statements."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=5) and title='Projeto: sistema web com banco de dados';

